import { readFileSync, writeFileSync } from 'node:fs'
const helper = readFileSync(new URL('install-windows.ps1', import.meta.url), 'utf8').replaceAll('\r\n', '\n')
const functions = helper.slice(
  helper.indexOf('function Assert-DiskWatchPath'),
  helper.lastIndexOf('\nInstall-DiskWatch -Installer'),
)
writeFileSync(
  new URL('../install.ps1', import.meta.url),
  '# Generated by scripts/build-windows-bootstrap.mjs\n' +
    functions +
    '\n' +
    readFileSync(new URL('bootstrap-windows.ps1', import.meta.url), 'utf8').replaceAll('\r\n', '\n'),
)
